import { defineConfig } from '@playwright/test'

/*
 * Visual-regression and axe suites for /dev/gallery (U09). See docs/design/VISUAL_TESTS.md.
 * The gallery is dev-only, so the server is a development-mode build served by `vite preview`
 * (no HMR socket, no dependency re-optimisation mid-run). Baselines are Linux-only: they are
 * generated by CI's Ubuntu runner, never on a developer machine.
 */
const PORT = 5199

export default defineConfig({
  testDir: 'e2e',
  // No platform suffix: there is exactly one set of baselines, the one CI produces.
  snapshotPathTemplate: '{testDir}/__screenshots__/{projectName}/{arg}{ext}',
  outputDir: 'test-results',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: 0,
  workers: process.env.CI ? 2 : undefined,
  reporter: process.env.CI ? [['list'], ['html', { open: 'never' }]] : 'list',
  expect: {
    toHaveScreenshot: { animations: 'disabled', caret: 'hide', scale: 'css', maxDiffPixelRatio: 0.002 },
  },
  use: {
    baseURL: `http://localhost:${PORT}`,
    browserName: 'chromium',
    locale: 'en-GB',
    timezoneId: 'Asia/Karachi',
    colorScheme: 'light',
    reducedMotion: 'reduce',
    deviceScaleFactor: 1,
    trace: 'retain-on-failure',
  },
  projects: [
    { name: 'w1440', use: { viewport: { width: 1440, height: 900 } } },
    { name: 'w375', use: { viewport: { width: 375, height: 812 } } },
  ],
  webServer: {
    command: `npm run build:e2e && npx vite preview --outDir dist-e2e --port ${PORT} --strictPort`,
    url: `http://localhost:${PORT}/`,
    reuseExistingServer: !process.env.CI,
    timeout: 180_000,
    env: { NODE_ENV: 'development' },
  },
})
